    uint256 attackerFinalBalanceInETH = attackerFinalcbETHBalance * CBETH_TO_ETH / 1e18 + attackerFinalrETHBalance * RETH_TO_ETH / 1e18;

    assertGt(attackerFinalBalanceInETH, attackerInitialValueInETH);
