        UserWithdrawalSummary storage userSummary = epochWithdrawals.users[withdrawer];
        userSummary.sharesOwed += SafeCast.toUint120(sharesOwed);

        emit WithdrawalQueued(currentEpoch, asset, withdrawer, sharesOwed, amountIn);
    }
```

